import express, { NextFunction, Request, Response } from "express";
import { TaskManagementService } from "../application/services";
import {
  ConflictError,
  NotFoundError,
  Task,
  TaskFilter,
  ValidationError,
  isTaskStatus,
} from "../domain/model";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
} from "./inMemoryRepositories";

function toDto(task: Task) {
  return { ...task, dueDate: task.dueDate ? task.dueDate.toISOString() : null };
}

function body(req: Request): Record<string, unknown> {
  const b: unknown = req.body;
  return typeof b === "object" && b !== null ? (b as Record<string, unknown>) : {};
}

function param(req: Request, name: string): string {
  const value = req.params[name];
  return typeof value === "string" ? value : "";
}

function queryString(req: Request, name: string): string | undefined {
  const value = req.query[name];
  if (value === undefined) return undefined;
  if (typeof value !== "string") throw new ValidationError(`${name} must be a single value`);
  return value;
}

export function createApp(service?: TaskManagementService): express.Express {
  const svc =
    service ??
    new TaskManagementService(
      new InMemoryUserRepository(),
      new InMemoryProjectRepository(),
      new InMemoryTaskRepository(),
    );
  const app = express();
  app.use(express.json());

  app.post("/users", (req, res) => {
    res.status(201).json(svc.createUser(body(req).name));
  });

  app.post("/projects", (req, res) => {
    res.status(201).json(svc.createProject(body(req).name));
  });

  app.get("/projects/:projectId", (req, res) => {
    res.json(svc.getProject(param(req, "projectId")));
  });

  app.post("/projects/:projectId/tasks", (req, res) => {
    const b = body(req);
    if (b.status !== undefined && !isTaskStatus(b.status)) {
      throw new ValidationError("status must be one of todo, in_progress, done");
    }
    if (b.assigneeId !== undefined && b.assigneeId !== null && typeof b.assigneeId !== "string") {
      throw new ValidationError("assigneeId must be a string");
    }
    const task = svc.addTask(param(req, "projectId"), {
      title: b.title,
      description: b.description,
      dueDate: b.dueDate,
      status: b.status,
      assigneeId: b.assigneeId,
    });
    res.status(201).json(toDto(task));
  });

  app.get("/projects/:projectId/tasks", (req, res) => {
    const filter: TaskFilter = {};
    const status = queryString(req, "status");
    if (status !== undefined) {
      if (!isTaskStatus(status)) {
        throw new ValidationError("status must be one of todo, in_progress, done");
      }
      filter.status = status;
    }
    const assignee = queryString(req, "assignee");
    if (assignee !== undefined) filter.assigneeId = assignee;
    res.json(svc.listTasks(param(req, "projectId"), filter).map(toDto));
  });

  app.put("/tasks/:taskId/assignee", (req, res) => {
    res.json(toDto(svc.assignTask(param(req, "taskId"), body(req).assigneeId)));
  });

  app.post("/tasks/:taskId/done", (req, res) => {
    res.json(toDto(svc.completeTask(param(req, "taskId"))));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof ValidationError) {
      res.status(400).json({ error: err.message });
    } else if (err instanceof NotFoundError) {
      res.status(404).json({ error: err.message });
    } else if (err instanceof ConflictError) {
      res.status(409).json({ error: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "Invalid JSON body" });
    } else {
      res.status(500).json({ error: "Internal server error" });
    }
  });

  return app;
}

